    // Privacy Policy Page
    privacyPolicyTitle: "Privacy Policy",
    privacyPolicyIntro1: "This Privacy Policy explains how Naioshfit (\"Naioshfit,\" \"we,\" \"our,\" or \"us\") collects, uses, and protects information when you use our fitness, nutrition, and progress-tracking platform available at",
    privacyPolicyIntro2: "and through our progressive web app, chat automations, emails, WhatsApp, or other support channels.",
    privacyPolicyIntro3: "By creating an account, submitting a form, or interacting with our services, you consent to the practices described below. If you disagree with this Policy, please discontinue use of Naioshfit.",
    privacySection1Title: "1. Who We Are",
    privacySection1Para1: "Naioshfit is a digitally delivered coaching service that pairs members with coaches, personalized nutrition plans, workout schedules, and progress dashboards. We operate from a fully remote team and host our infrastructure with trusted cloud providers such as Railway and Vercel.",
    privacySection1Para2: "Contact us any time at",
    privacySection2Title: "2. Information We Collect",
    privacySection2Para1: "We collect information that helps us deliver accurate coaching and keep your account secure:",
    privacySection2Item1: "Account & Identity Data: name, username, contact details, date of birth, preferred language, and authentication credentials.",
    privacySection2Item2: "Body Metrics & Training Data: biometrics, medical disclosures you choose to share, progress photos, nutrition habits, supplements, training frequency, and survey submissions.",
    privacySection2Item3: "Device & Technical Data: IP address, browser type, device identifiers, and diagnostics collected via cookies or analytics.",
    privacySection2Item4: "Communications: messages exchanged with coaches or support via in-app chat, WhatsApp, email, or connected Meta channels.",
    privacySection2Item5: "Payments & Subscriptions: transaction identifiers, plan selection, and status. Payment card data is processed securely by our payment partners and never stored in plain text by Naioshfit.",
    privacySection2Item6: "Uploaded Content: attachments such as meal receipts, lab results, or progress documents that you voluntarily provide.",
    privacySection3Title: "3. How We Use Your Information",
    privacySection3Para1: "Naioshfit processes data to:",
    privacySection3Item1: "Create and manage user accounts, logins, and referral programs.",
    privacySection3Item2: "Design customized training blocks, daily macros, and accountability reminders.",
    privacySection3Item3: "Monitor adherence, generate dashboards, and surface insights about energy intake, weight trends, or workout compliance.",
    privacySection3Item4: "Provide customer support, resolve technical issues, and send service or safety notices.",
    privacySection3Item5: "Improve our digital experiences, detect abuse, and measure engagement across campaigns.",
    privacySection3Item6: "Meet legal, tax, and auditing obligations, including safeguarding requests from law enforcement when applicable.",
    privacySection4Title: "4. Legal Bases for Processing",
    privacySection4Para1: "Depending on where you live, we rely on one or more of the following legal bases:",
    privacySection4Item1: "Performance of a Contract to deliver the coaching plan or subscription you selected.",
    privacySection4Item2: "Legitimate Interest to secure our platform, prevent fraud, and grow the Naioshfit product responsibly.",
    privacySection4Item3: "Consent when you volunteer sensitive health details, enable marketing emails, or install our PWA.",
    privacySection4Item4: "Legal Obligation to comply with applicable health, tax, or consumer-protection regulations.",
    privacySection5Title: "5. How We Share Information",
    privacySection5Para1: "We do not sell or rent your personal information. We may share limited data with:",
    privacySection5Item1: "Technology vendors who host infrastructure, analytics, messaging, or file storage (e.g., Railway, AWS, Meta, OpenAI).",
    privacySection5Item2: "Authorized coaches and support specialists who need access to serve your account.",
    privacySection5Item3: "Payment processors and banking partners that complete your transactions.",
    privacySection5Item4: "Civic authorities when compelled by valid legal requests.",
    privacySection5Para2: "All vendors are bound by confidentiality and data-processing agreements.",
    privacySection6Title: "6. Data Retention",
    privacySection6Para1: "We retain account and coaching history for as long as you maintain a subscription or as needed to provide services. Progress photos and sensitive health notes can be deleted at your request, and we routinely purge dormant accounts after 24 months of inactivity unless law requires longer retention.",
    privacySection7Title: "7. Security",
    privacySection7Para1: "Naioshfit applies SSL encryption, role-based access, daily backups, and continuous monitoring. No method of transmission is 100% secure, so we encourage you to use strong passwords and enable device-level protections.",
    privacySection8Title: "8. International Transfers",
    privacySection8Para1: "Our servers may be located outside your country of residence. By using Naioshfit you consent to transferring information to jurisdictions that may have different data protection laws. We implement standard contractual clauses or equivalent safeguards where required.",
    privacySection9Title: "9. Your Choices & Rights",
    privacySection9Para1: "Depending on local laws, you may have the right to:",
    privacySection9Item1: "Access, update, or correct information from the profile settings or by emailing us.",
    privacySection9Item2: "Download a copy of the data we maintain about you.",
    privacySection9Item3: "Request deletion of your account and associated content.",
    privacySection9Item4: "Object to certain processing or withdraw consent without affecting the lawfulness of prior processing.",
    privacySection9Item5: "Disable cookies via your browser or device settings.",
    privacySection10Title: "10. Children's Privacy",
    privacySection10Para1: "Naioshfit is designed for adults 18+. We do not knowingly collect data from children. If we discover that a minor has provided information, we will delete it promptly and may suspend the related account.",
    privacySection11Title: "11. Updates to This Policy",
    privacySection11Para1: "We will post any privacy updates on this page and adjust the \"Last Updated\" date. Material changes may also be communicated by email or in-app notification.",
    privacySection12Title: "12. Contact Us",
    privacySection12Para1: "For privacy requests, please email",
