    // Terms of Service Page
    termsOfServiceTitle: "Terms of Service",
    tosIntro: "These Terms of Service (\"Terms\") govern your use of Naioshfit, our progressive web app, dashboards, messaging channels, and any other services we provide (collectively, the \"Services\"). By creating an account, subscribing to a plan, or otherwise accessing Naioshfit, you agree to these Terms. If you do not agree, please discontinue use immediately.",
    tosSection1Title: "1. Eligibility & Account Responsibilities",
    tosSection1Item1: "You must be at least 18 years old and capable of entering into a binding agreement.",
    tosSection1Item2: "You agree to provide accurate profile, health, and billing information and to keep it up to date.",
    tosSection1Item3: "You are responsible for maintaining the confidentiality of your login credentials and for all activity under your account.",
    tosSection1Item4: "If you suspect unauthorized use, notify us at support@naioshfit.com immediately.",
    tosSection2Title: "2. Coaching & Health Disclaimers",
    tosSection2Item1: "Naioshfit provides digital coaching and educational content. We are not a medical provider and do not diagnose, treat, or prescribe.",
    tosSection2Item2: "Always consult a qualified healthcare professional before starting any fitness or nutrition program, especially if you have pre-existing conditions.",
    tosSection2Item3: "You acknowledge that physical activity carries inherent risks and you participate voluntarily.",
    tosSection3Title: "3. Subscriptions, Billing & Refunds",
    tosSection3Item1: "Plans renew automatically at the interval you select until canceled. Renewal charges are processed using your saved payment method.",
    tosSection3Item2: "Fees are non-refundable except where required by law or explicitly stated in an offer. We may issue credits at our sole discretion.",
    tosSection3Item3: "You authorize Naioshfit and its payment partners to collect applicable taxes and exchange fees.",
    tosSection3Item4: "You can update payment information or cancel future renewals from the billing settings or by emailing us.",
    tosSection4Title: "4. Acceptable Use",
    tosSection4Para1: "You agree not to:",
    tosSection4Item1: "Share, resell, or sublicense access to your account.",
    tosSection4Item2: "Upload content that infringes, is abusive, or violates the privacy of others.",
    tosSection4Item3: "Reverse engineer, probe, or interfere with the platform, APIs, or security controls.",
    tosSection4Item4: "Misrepresent yourself as a Naioshfit coach or employee.",
    tosSection5Title: "5. Intellectual Property",
    tosSection5Para1: "Naioshfit, including the dashboards, code, branding, videos, and written content, is protected by intellectual property laws. We grant you a limited, non-transferable license to use the Services for personal fitness purposes while your subscription is active. You may not copy or create derivative works without written consent.",
    tosSection6Title: "6. Termination",
    tosSection6Para1: "We may suspend or terminate access if you violate these Terms, misuse the Services, or fail to pay applicable fees. You may terminate at any time by canceling your subscription; however, prepaid fees will not be refunded unless legally required. Upon termination, your access to coaching materials and stored data may be limited or removed.",
    tosSection7Title: "7. Limitation of Liability",
    tosSection7Para1: "To the maximum extent permitted by law, Naioshfit is not liable for indirect, incidental, punitive, or consequential damages arising from your use of the Services. Our total liability for any claim will not exceed the amount you paid to Naioshfit in the six months preceding the claim. Some jurisdictions do not allow certain limitations, so the above may not apply to you.",
    tosSection8Title: "8. Privacy & Data",
    tosSection8Para1: "Our Privacy Policy explains how we collect and process personal data. By using Naioshfit you acknowledge that your information will be handled as described there, including transfers to third-party processors and international locations.",
    tosSection9Title: "9. Changes to the Services or Terms",
    tosSection9Para1: "We may update the Services, pricing, or these Terms from time to time. When material changes occur we will notify you via email, in-app message, or by updating the \"Last Updated\" date. Continuing to use Naioshfit after changes become effective constitutes acceptance of the revised Terms.",
    tosSection10Title: "10. Governing Law",
    tosSection10Para1: "These Terms are governed by the laws of the jurisdiction in which Naioshfit operates, without regard to conflict of law principles. Any disputes will be handled through good-faith negotiations and, if necessary, in the courts of that jurisdiction.",
    tosSection11Title: "11. Contact",
    tosSection11Para1: "Questions about these Terms? Reach us at",
    
